    export type updateDepartmentResponse200 = {
  data: DepartmentDTO
  status: 200
}

export type updateDepartmentResponseDefault = {
  data: ErrorModel
  status: Exclude<HTTPStatusCodes, 200>
}

export type updateDepartmentResponseSuccess = (updateDepartmentResponse200) & {
  headers: Headers;
};
export type updateDepartmentResponseError = (updateDepartmentResponseDefault) & {
  headers: Headers;
};

export type updateDepartmentResponse = (updateDepartmentResponseSuccess | updateDepartmentResponseError)

export const getUpdateDepartmentUrl = (id: string,) => {




  return `/api/departments/${id}`
}

/**
 * @summary Update a department
 */
export const updateDepartment = async (id: string,
    updateDepartmentInputBody: NonReadonly<UpdateDepartmentInputBody>, options?: Parameters<typeof customInstance>[1]): Promise<updateDepartmentResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
return customInstance<updateDepartmentResponse>(getUpdateDepartmentUrl(id),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(updateDepartmentInputBody)
  }
);}





export const getUpdateDepartmentMutationKey = () => ['updateDepartment'] as const;

export const getUpdateDepartmentMutationOptions = <TError = ErrorModel,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateDepartment>>, TError,UpdateDepartmentMutationVariables, TContext>, request?: SecondParameter<typeof customInstance>}
): UseMutationOptions<Awaited<ReturnType<typeof updateDepartment>>, TError,UpdateDepartmentMutationVariables, TContext> => {

const mutationKey = getUpdateDepartmentMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof updateDepartment>>, UpdateDepartmentMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  updateDepartment(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UpdateDepartmentMutationResult = NonNullable<Awaited<ReturnType<typeof updateDepartment>>>
    export type UpdateDepartmentMutationBody = NonReadonly<UpdateDepartmentInputBody>
    export type UpdateDepartmentMutationError = ErrorModel
    export type UpdateDepartmentMutationVariables = {id: string;data: NonReadonly<UpdateDepartmentInputBody>}

    /**
 * @summary Update a department
 */
export const useUpdateDepartment = <TError = ErrorModel,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateDepartment>>, TError,UpdateDepartmentMutationVariables, TContext>, request?: SecondParameter<typeof customInstance>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof updateDepartment>>,
        TError,
        UpdateDepartmentMutationVariables,
        TContext
      > => {
      return useMutation(getUpdateDepartmentMutationOptions(options), queryClient);
    }
